mapper.select:
select id, idempotency_key, operator_id, request_method, request_path, request_hash,
       status, response_status, response_body, created_at, expires_at
from account_idempotency_records
where operator_id = #{operatorId}
  and request_method = #{requestMethod}
  and request_path = #{requestPath}
  and idempotency_key = #{idempotencyKey}
  and expires_at > #{now}

mapper.delete:
delete from account_idempotency_records
where operator_id = #{operatorId}
  and request_method = #{requestMethod}
  and request_path = #{requestPath}
  and idempotency_key = #{idempotencyKey}
  and expires_at <= #{now}
